    validity_level VARCHAR(12) NOT NULL DEFAULT ''
        CHECK (validity_level IN ('valid', 'invalid', 'incomplete', ''))
);

CREATE TRIGGER trigger_grading_fired_rule_updated_at
    BEFORE UPDATE ON grading_fired_rule
